package cn.linkdeck.adb;
import android.content.*;import android.net.wifi.WifiManager;import android.net.nsd.*;import android.os.*;import java.util.*;
/** User-initiated, bounded mDNS discovery. Discovery never authorizes or connects a device. */
public final class LanDiscovery implements AutoCloseable {
 public interface Listener {void found(String host,int port,String type);void done(int count);default void error(int code){}}
 private final NsdManager manager;private WifiManager.MulticastLock multicast;private final Handler ui=new Handler(Looper.getMainLooper());private final List<NsdManager.DiscoveryListener> active=new ArrayList<>();private final Queue<NsdServiceInfo> waiting=new ArrayDeque<>();private final Set<String> seen=new HashSet<>();private boolean stopped,resolving;private final Listener listener;private final Runnable timeout;
 public LanDiscovery(Context c,Listener l){manager=(NsdManager)c.getSystemService(Context.NSD_SERVICE);listener=l;timeout=()->{if(!stopped){close();listener.done(seen.size());}};try{WifiManager wifi=(WifiManager)c.getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wifi!=null){multicast=wifi.createMulticastLock("linkdeck-adb-discovery");multicast.setReferenceCounted(false);}}catch(Exception ignored){}}
 public void start(){try{if(multicast!=null)multicast.acquire();}catch(Exception ignored){}for(String type:new String[]{"_adb._tcp.","_adb-tls-pairing._tcp.","_adb-tls-connect._tcp."}){NsdManager.DiscoveryListener d=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String t){}public void onDiscoveryStopped(String t){}public void onStartDiscoveryFailed(String t,int e){ui.post(()->{if(!stopped)listener.error(e);});}public void onStopDiscoveryFailed(String t,int e){}public void onServiceLost(NsdServiceInfo i){}public void onServiceFound(NsdServiceInfo i){ui.post(()->{if(!stopped&&waiting.size()<32){waiting.offer(i);resolve();}});}};active.add(d);try{manager.discoverServices(type,NsdManager.PROTOCOL_DNS_SD,d);}catch(Exception ignored){listener.error(-1);}}ui.postDelayed(timeout,8000);}
 private void resolve(){if(stopped||resolving||waiting.isEmpty())return;resolving=true;NsdServiceInfo service=waiting.poll();try{manager.resolveService(service,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo i,int e){ui.post(()->{resolving=false;resolve();});}public void onServiceResolved(NsdServiceInfo i){ui.post(()->{resolving=false;if(!stopped&&i.getHost()!=null&&i.getPort()>0){String host=i.getHost().getHostAddress(),type=i.getServiceType();if(type==null)type=service.getServiceType();String key=host+":"+i.getPort()+":"+type;if(seen.add(key))listener.found(host,i.getPort(),type);}resolve();});}});}catch(Exception e){resolving=false;resolve();}}
 public void close(){if(stopped)return;stopped=true;ui.removeCallbacks(timeout);if(multicast!=null&&multicast.isHeld())try{multicast.release();}catch(Exception ignored){}for(NsdManager.DiscoveryListener d:active)try{manager.stopServiceDiscovery(d);}catch(Exception ignored){}active.clear();waiting.clear();}
}
